def may_access(proc, f, want):
    if proc.has_cap_dac_override:   # root
        return True     # simplified: exec still needs one x bit
    if proc.uid == f.owner:
        bits = f.owner_bits
    elif f.group in proc.groups:
        bits = f.group_bits
    else:
        bits = f.other_bits
    return want in bits

